//========================================================================
// BLOCK 1: ADJUSTABLE MATRIX CONFIGURATION
//========================================================================
const matrixConfig = {
  ranges: {
    revenue: { min: 0, max: 10000000, weight: 40 },
    employees: { min: 0, max: 500, weight: 30 }
  },
  weights: {
    funding: {
      "public": 15, "ipo": 15, "series d": 15, "series c": 15, 
      "series b": 12, "series a": 10, "seed": 5, "bootstrapped": 2
    },
    intent: {
      "sales_contact": 50,
      "demo_request": 40,
      "pricing_interest": 30,
      "product_exploration": 20,
      "resource_interest": 10
    }
  },
  tierThresholds: {
    Tier_1: 55,
    Tier_2: 20
  },
  // High-intent signals eligible for edge-case rescue
  intentOverrides: [
    "sales_contact",
    "demo_request"
  ]
};

//========================================================================
// BLOCK 2: DETERMINISTIC SCORING ENGINE WITH GUARDED OVERRIDES
//========================================================================

const getFlexibleValue = (obj, targetKey) => {
  if (!obj) return undefined;
  const matchPattern = targetKey.toLowerCase().replace(/[\s_-]+/g, '');
  for (const key of Object.keys(obj)) {
    if (key.toLowerCase().replace(/[\s_-]+/g, '') === matchPattern) {
      return obj[key];
    }
  }
  return undefined;
};

// safe number parser
const cleanNumber = (val) => {
  if (!val || val === -1) return 0;
  const cleaned = String(val).replace(/[^0-9.]/g, '');
  const parsed = parseFloat(cleaned);
  return isNaN(parsed) ? 0 : parsed;
};

// 1. Ingestion Layer Extraction
const dataSource = $json.body ?? $json;

const rawRevenue   = getFlexibleValue(dataSource, 'annual_revenue') ?? getFlexibleValue($json, 'annual_revenue') ?? 0;
const rawEmployees = getFlexibleValue(dataSource, 'employee_count') ?? getFlexibleValue($json, 'employee_count') ?? 0;
const rawFunding   = getFlexibleValue(dataSource, 'funding_stage') ?? getFlexibleValue($json, 'funding_stage') ?? "";
const rawIntent    = getFlexibleValue(dataSource, 'intent_signal') ?? getFlexibleValue($json, 'intent_signal') ?? "";
const enrichSource = getFlexibleValue(dataSource, 'enrichment_source') ?? getFlexibleValue($json, 'enrichment_source') ?? "";

const revenue      = cleanNumber(rawRevenue);
const employees    = cleanNumber(rawEmployees);
const fundingStage = String(rawFunding).toLowerCase().trim();
const cleanIntent  = String(rawIntent).toLowerCase().replace(/[\s_-]+/g, '').trim();

// 2. Point Calculations
let intentPoints = 0;
for (const key of Object.keys(matrixConfig.weights.intent)) {
  if (key.toLowerCase().replace(/[\s_-]+/g, '') === cleanIntent) {
    intentPoints = matrixConfig.weights.intent[key];
    break;
  }
}

const fundingPoints = matrixConfig.weights.funding[fundingStage] ?? 2;

const revCfg = matrixConfig.ranges.revenue;
const boundedRev = Math.min(Math.max(revenue, revCfg.min), revCfg.max);
const revenuePoints = (((boundedRev - revCfg.min) / (revCfg.max - revCfg.min || 1)) * revCfg.weight);

const empCfg = matrixConfig.ranges.employees;
const boundedEmp = Math.min(Math.max(employees, empCfg.min), empCfg.max);
const employeePoints = (((boundedEmp - empCfg.min) / (empCfg.max - empCfg.min || 1)) * empCfg.weight);

const totalLeadScore = Math.round(revenuePoints + employeePoints + fundingPoints + intentPoints);

// 3. Guarded Override Tier Resolution
let allocatedTier = "Tier-3";
let isPriorityOverride = false;
let overrideReason = "No override triggered";

const isHighIntent = matrixConfig.intentOverrides.some(
  override => override.toLowerCase().replace(/[\s_-]+/g, '') === cleanIntent
);

// Check if domain was reachable/valid
const isValidDomainScrape = enrichSource !== "META_SCRAPER_FAILED";

if (totalLeadScore >= matrixConfig.tierThresholds.Tier_1) {
  allocatedTier = "Tier-1";
} else if (totalLeadScore >= matrixConfig.tierThresholds.Tier_2) {
  allocatedTier = "Tier-2";
} else if (isHighIntent && isValidDomainScrape) {
  // EDGE CASE RESCUE: High intent on a valid/active domain elevates score to Tier-2
  allocatedTier = "Tier-2";
  isPriorityOverride = true;
  overrideReason = `Rescued via High-Intent (${rawIntent}) on valid domain`;
} else {
  allocatedTier = "Tier-3";
}

// 4. Output Integration
return {
  ...$json,
  total_lead_score: totalLeadScore,
  allocated_tier: allocatedTier,
  revenue_points: Math.round(revenuePoints),
  employee_points: Math.round(employeePoints),
  funding_points: fundingPoints,
  intent_points: intentPoints,
  is_priority_override: isPriorityOverride,
  override_reason: overrideReason,
  company_description: $json.company_description || $json.description || $json.short_description || 'N/A',
  raw_meta_summary: $json.raw_meta_summary || 'Enriched via Primary Apollo API',
  enrichment_source: $json.enrichment_source || 'APOLLO',
  enrichment_success: $json.enrichment_success !== undefined ? $json.enrichment_success : true
};

//=========================================================================
// PRODUCTION KEYWORD SAFETY CATCH TIER-3 (V1.0)
//=========================================================================

// Config
const safetyConfig = {
  companyKeywords: [
    "venture", "fund", "incubator", "accelerator", "artificial intelligence", 
    "startup", "defense", "military", "aerospace", "quantum", "enterprise"
  ],
  executiveHandles: [
    "ceo", "founder", "cofounder", "co-founder", "partner", "director", "owner"
  ],
  rescueFundingStages: [
    "series b", "series c", "public"
  ]
};

// Extracted context values
const status = String($json.status || "").toUpperCase();
const enrichSource = String($json.enrichment_source || "").toUpperCase();

const isFailedEnrichment = (status === "ENRICHMENT_FAILED" || enrichSource === "META_SCRAPER_FAILED");

const description = String($json.company_description || "").toLowerCase();
const industry = String($json.industry || "").toLowerCase();
const email = String($json.email || "").toLowerCase();
const fundingStage = String($json.funding_stage || "").toLowerCase().trim();
const companyKeywords = String($json.company_keywords || "").toLowerCase();

const emailPrefix = email.split("@")[0] || "";

let isPriorityOverride = false;
let overrideReason = "";

// =========================================================================
// COMPONENT 1: Executive Capacity Check (Runs even on unknown domains)
// =========================================================================
const emailTokens = emailPrefix.split(/[^a-z0-9]+/);

if (emailTokens.length > 0) {
  const firstToken = emailTokens[0];
  for (const handle of safetyConfig.executiveHandles) {
    const cleanHandle = handle.toLowerCase().replace(/[^a-z0-9]+/g, '');
    if (firstToken === cleanHandle) {
      isPriorityOverride = true;
      overrideReason = `Executive capacity detected in email: "${handle}"`;
      break;
    }
  }
}

// =========================================================================
// COMPONENT 2: Funding-Stage Rescue (Requires valid company data)
// =========================================================================
if (!isPriorityOverride && !isFailedEnrichment && safetyConfig.rescueFundingStages.includes(fundingStage)) {
  isPriorityOverride = true;
  overrideReason = `High-capacity funding stage matched: "${fundingStage}"`;
}

// =========================================================================
// COMPONENT 3: Firmographic Keyword Check (Guarded against failed scrapes)
// =========================================================================
if (!isPriorityOverride && !isFailedEnrichment) {
  for (const keyword of safetyConfig.companyKeywords) {
    if (
      description.includes(keyword) || 
      industry.includes(keyword) || 
      companyKeywords.includes(keyword)
    ) {
      isPriorityOverride = true;
      overrideReason = `High-capacity industry keyword matched: "${keyword}"`;
      break;
    }
  }
}

return {
  ...$json,
  allocated_tier: "Tier-3", 
  is_priority_override: isPriorityOverride,
  override_reason: overrideReason || "No override triggered"
};

// ====================================================================
// GENERIC OUTPUT AGGREGATOR
// Mode: Run Once for Each Item
// ====================================================================

let lead = {};

try {
  lead = $('Active Leads').item.json ?? {};
} catch (e) {
  lead = {};
}

const current = $json ?? {};

const aiBattlecard =
  current.text ||
  lead.ai_draft ||
  "AI Battlecard temporarily unavailable. Ready to notify";

return {
  ...lead,
  ...current,
  ai_battlecard: String(aiBattlecard).trim()
};

