// =====================================================================
// PRODUCTION PAYLOAD VERIFIER & FLATTENER — ZERO-TRUST GATE
// Finds the required lead object anywhere inside the incoming payload.
// =====================================================================

const REQUIRED_FIELDS = [
  "first_name",
  "email",
  "intent_signal",
  "honeypot_bypass"
];

// ---------------------------------------------------------------------
// 1. Recursively search the ENTIRE payload for one object containing
//    all four required fields.
// ---------------------------------------------------------------------

const findLeadObject = (value) => {
  if (!value || typeof value !== "object") return null;

  if (!Array.isArray(value)) {
    const hasAllFields = REQUIRED_FIELDS.every(
      field => Object.prototype.hasOwnProperty.call(value, field)
    );

    if (hasAllFields) {
      return value;
    }
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findLeadObject(item);
      if (found) return found;
    }
  } else {
    for (const key of Object.keys(value)) {
      const found = findLeadObject(value[key]);
      if (found) return found;
    }
  }

  return null;
};

const incomingPayload = $json;

const incoming = findLeadObject(incomingPayload);

if (!incoming) {
  throw new Error(
    "Validation Stopped: Required lead payload containing first_name, email, intent_signal, and honeypot_bypass was not found."
  );
}

// ---------------------------------------------------------------------
// 2. Extract ONLY the four allowed fields.
// ---------------------------------------------------------------------

const normalize = (value) => {
  if (value === undefined || value === null) return "";

  return String(value)
    .replace(/[\r\n\t\0]/g, "")
    .trim();
};

const extractedPayload = {
  first_name: normalize(incoming.first_name),
  email: normalize(incoming.email).toLowerCase(),
  intent_signal: normalize(incoming.intent_signal),
  honeypot_bypass: normalize(incoming.honeypot_bypass)
};

// =====================================================================
// 3. EXISTING VALIDATION / BUSINESS RULES
// =====================================================================

// Required Field Check: Email
if (extractedPayload.email.length === 0) {
  throw new Error(
    "Validation Stopped: Email field is completely empty or missing."
  );
}

// Required Field Check: Intent Signal
if (extractedPayload.intent_signal.length === 0) {
  throw new Error(
    "Validation Stopped: Required field 'intent_signal' is missing."
  );
}

// Strict Email Regex
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(extractedPayload.email)) {
  throw new Error(
    `Validation Stopped: Provided email '${extractedPayload.email}' is malformed.`
  );
}

// Honeypot
if (extractedPayload.honeypot_bypass.length > 0) {
  throw new Error(
    "Validation Stopped: Spam bot honeypot trap field was triggered."
  );
}

// First-name fallback
if (!extractedPayload.first_name) {
  extractedPayload.first_name =
    extractedPayload.email.split("@")[0];
}

// =====================================================================
// 4. RETURN ONLY THE CLEAN FOUR-FIELD PAYLOAD
// =====================================================================

return {
  first_name: extractedPayload.first_name,
  email: extractedPayload.email,
  intent_signal: extractedPayload.intent_signal,
  honeypot_bypass: extractedPayload.honeypot_bypass
};

//========================================================================
// 1.CONFIGURATION 
// Select ONLY the enriched fields the client wants appended to their payload.
//========================================================================
const CLIENT_CONFIG = {
  enrichment_fields: [
    "company_name",
    "employee_count",
    "annual_revenue",
    "industry",
    "funding_stage",
    "company_country",
    "company_description",
    "company_keywords"
  ]
};

//========================================================================
// 2. INPUT DATA SOURCES
//========================================================================

// RAW ENRICHMENT DATA (from current node context / Apollo)
const rawEnrichment = $json || {};

// EARLIER PAYLOAD (Hooked up from an upstream n8n node)
let basePayload = {};
try {
  // TODO: Replace '1' or node name with your upstream lead node when ready
  basePayload = $('Lead Registry').item.json || {};
} catch (e) {
  // Safe fallback if upstream node is not linked yet
  basePayload = {};
}

// Optional Webhook source fallback for incoming leads
let webhookData = {};
try {
  webhookData = $('Webhook Ingestion Gate').item.json || {};
} catch (e) {
  webhookData = {};
}

//========================================================================
// 3. FIXED HELPERS
//========================================================================
const findField = (fieldKey, fallback) => {
  if (rawEnrichment.organization && rawEnrichment.organization[fieldKey] !== undefined && rawEnrichment.organization[fieldKey] !== null) {
    return String(rawEnrichment.organization[fieldKey]).trim();
  }
  if (rawEnrichment[fieldKey] !== undefined && rawEnrichment[fieldKey] !== null) {
    return String(rawEnrichment[fieldKey]).trim();
  }
  return fallback;
};

const rawCompanyName = findField('name', '').trim();
const isEnrichmentValid = rawCompanyName.length > 0;

const cleanNumericString = (rawVal) => {
  if (rawVal === undefined || rawVal === null) return "0";
  const cleaned = String(rawVal).replace(/[^0-9.]/g, '');
  return cleaned || "0";
};

const getKeywordsString = () => {
  if (!isEnrichmentValid) return "NONE";
  const rawKeywords = (rawEnrichment.organization && rawEnrichment.organization.keywords) || rawEnrichment.keywords;
  if (Array.isArray(rawKeywords)) {
    const cleanedArray = rawKeywords.map(k => String(k).toLowerCase().trim()).filter(Boolean);
    return cleanedArray.length > 0 ? cleanedArray.join(', ') : "NONE";
  }
  return "NONE";
};

const rawIntent = basePayload.intent_signal || basePayload["Intent Signal"] || webhookData.intent_signal || "pricing_page_demo";
const normalizedIntent = String(rawIntent).toLowerCase().replace(/[\s_-]+/g, '_').trim();

//========================================================================
// 4. CORE ENGINE & FILTERING
//========================================================================

// Step A: Base core fields (Always retained)

const corePayload = {
  lead_id: String(basePayload.lead_id || rawEnrichment.lead_id || ""),
  first_name: String(basePayload.first_name || rawEnrichment.first_name || ""),
  email: String(basePayload.email || rawEnrichment.email || ""),
  extracted_domain: String(basePayload.extracted_domain || rawEnrichment.extracted_domain || ""),
  is_enterprise_domain: (basePayload.is_enterprise_domain || rawEnrichment.is_enterprise_domain),
  domain_system_warning: String(basePayload.domain_system_warning || "NONE"),
  status: isEnrichmentValid ? (basePayload.status || "REGISTERED") : "ENRICHMENT_FAILED",
  intent_signal: normalizedIntent
};

// Step B: Full possible enrichment pool

const availableEnrichment = {
  company_name: isEnrichmentValid ? rawCompanyName : "EMPTY",
  employee_count: isEnrichmentValid ? (parseInt(cleanNumericString(findField('estimated_num_employees', '0')), 10) || 0) : -1,
  annual_revenue: isEnrichmentValid ? (parseFloat(cleanNumericString(findField('annual_revenue', '0'))) || 0) : -1,
  industry: isEnrichmentValid ? findField('industry', 'EMPTY') : "EMPTY",
  funding_stage: isEnrichmentValid ? findField('latest_funding_stage', 'EMPTY') : "EMPTY",
  company_country: isEnrichmentValid ? findField('country', 'EMPTY') : "EMPTY",
  company_description: isEnrichmentValid ? findField('seo_description', findField('short_description', 'EMPTY')) : "EMPTY",
  company_keywords: getKeywordsString()
};

// Step C: Append only the client-selected fields to the core payload
const finalOutput = { ...corePayload };

for (const fieldKey of CLIENT_CONFIG.enrichment_fields) {
  if (fieldKey in availableEnrichment) {
    finalOutput[fieldKey] = availableEnrichment[fieldKey];
  }
}

return finalOutput;

// =====================================================================
// STEP 1: PRODUCTION DOMAIN CLEANER & EMAIL NORMALIZER
// =====================================================================

const rawEmail = $json.email ?? "";
const cleanEmail = String(rawEmail).toLowerCase().trim();

const consumerProviders = [
  "gmail.com",
  "yahoo.com",
  "hotmail.com",
  "outlook.com",
  "protonmail.com",
  "proton.me",
  "icloud.com",
  "aol.com",
  "zoho.com",
  "yandex.com",
  "mail.com",
  "gmx.com"
];

// 1. Email Existence Check
if (cleanEmail.length === 0) {
  throw new Error("Registration Failed: Inbound email field was completely empty.");
}

// 2. Structural Email & Domain Parsing
if (!cleanEmail.includes("@")) {
  throw new Error("Registration Failed: Inbound string missing '@' symbol.");
}

const emailParts = cleanEmail.split("@");

if (emailParts.length !== 2) {
  throw new Error("Registration Failed: Email contains an invalid number of '@' symbols.");
}

const domainPart = emailParts[1].trim();

if (domainPart.length === 0 || !domainPart.includes(".")) {
  throw new Error("Registration Failed: Email domain is invalid or missing TLD.");
}

// 3. Domain Classification
const extractedDomain = domainPart;
const isEnterpriseDomain = !consumerProviders.includes(extractedDomain);

// 4. Return Normalized Payload (Clean Email + Domain Info)
return {
  ...$json,
  email: cleanEmail,
  extracted_domain: extractedDomain,
  is_enterprise_domain: isEnterpriseDomain,
  domain_system_warning: "NONE"
};

// ====================================================================
// LEAD FREQUENCY & INTENT ENGINE
// ====================================================================
// Purpose:
//   Calculate lead heat using:
//   1. Intent
//   2. Event velocity
//   3. Intent upgrades
//   4. Accumulated heat
//
// IMPORTANT:
//   Business rules live ONLY in CONFIGURATION.
//   Do not put scoring rules elsewhere in the workflow.
// ====================================================================

const item = $input.item.json;

// ====================================================================
// CONFIGURATION
// ====================================================================
// Change business rules here only.
// ====================================================================

const config = {
  // Events occurring faster than this are treated as
  // bot/double-click/debounce activity.
  debounce_seconds: 3,

  // Intent matrix
  // higher intent to lower intent 
  signal_matrix: {
    sales_contact: {
      rank: 1,
      base_points: 50
    },

    demo_request: {
      rank: 2,
      base_points: 40
    },

    pricing_interest: {
      rank: 3,
      base_points: 30
    },

    product_exploration: {
      rank: 3,
      base_points: 20
    },

    resource_interest: {
      rank: 3,
      base_points: 10
    },

  },

  // Velocity scoring
  velocity_thresholds: [
    {
      max_seconds: 900,       // 15 minutes
      multiplier: 1.5
    },
    {
      max_seconds: 86400,     // 24 hours
      multiplier: 1.2
    },
    {
      max_seconds: null,      // anything beyond 24 hours
      multiplier: 1.0
    }
  ],

  // Intent upgrade bonus
  surge_bonus_points: 20,

  // Heat classification
  heat_thresholds: {
    warm_min: 26,
    hot_min: 51,
    hottest_min: 81
  }
};


// ====================================================================
// SECTION 1: VALIDATE INPUT
// ====================================================================

const email = item.email;

if (!email) {
  throw new Error('Lead Frequency Engine: missing email');
}

const incomingSignal = item.intent_signal;

if (!incomingSignal) {
  throw new Error('Lead Frequency Engine: missing intent_signal');
}


// ====================================================================
// SECTION 2: RESOLVE CURRENT INTENT
// ====================================================================

const signalConfig = config.signal_matrix[incomingSignal];

if (!signalConfig) {
  throw new Error(
    `Lead Frequency Engine: unknown intent_signal "${incomingSignal}"`
  );
}

const currentRank = Number(signalConfig.rank);
const basePoints = Number(signalConfig.base_points);


// ====================================================================
// SECTION 3: READ PREVIOUS DB STATE
// ====================================================================

const previousRank = Number(
  item.last_intent_rank ?? currentRank
);

const previousScore = Number(
  item.heat_score ?? 0
);

const previousTouchpoints = Number(
  item.total_touchpoints ?? 0
);


// ====================================================================
// SECTION 4: CALCULATE EVENT VELOCITY
// ====================================================================
//
// Delta T = NOW - last_event_at
//
// < 3 seconds       → 0.0x
// 3 sec–15 minutes  → 1.5x
// >15 min–24 hours  → 1.2x
// >24 hours         → 1.0x
//
// ====================================================================

const nowMs = Date.now();

let deltaTSeconds = 0;

if (item.last_event_at) {

  const lastEventMs = new Date(item.last_event_at).getTime();

  if (!Number.isNaN(lastEventMs)) {

    deltaTSeconds = Math.max(
      0,
      Math.floor((nowMs - lastEventMs) / 1000)
    );

  }
}


// Resolve velocity multiplier from configuration.
const velocityRule = config.velocity_thresholds.find(rule => {

  return (
    rule.max_seconds === null ||
    deltaTSeconds <= Number(rule.max_seconds)
  );

});

if (!velocityRule) {
  throw new Error(
    `Lead Frequency Engine: no velocity rule matched delta_t_seconds=${deltaTSeconds}`
  );
}

const velocityMultiplier =
  deltaTSeconds < config.debounce_seconds
    ? 0
    : Number(velocityRule.multiplier);


// ====================================================================
// SECTION 5: INTENT SURGE
// ====================================================================
//
// Rank 1 = highest intent.
//
// Therefore:
//
// 3 → 2 = upgrade
// 3 → 1 = upgrade
// 2 → 1 = upgrade
//
// Formula:
//
// Delta R = previousRank - currentRank
//
// If Delta R > 0 → intent upgraded → +20
//
// ====================================================================

const deltaRank = previousRank - currentRank;

const isIntentUpgrade = deltaRank > 0;

const surgeBonus = isIntentUpgrade
  ? Number(config.surge_bonus_points)
  : 0;


// ====================================================================
// SECTION 6: CALCULATE EARNED POINTS
// ====================================================================

const earnedPoints = Math.round(
  (basePoints * velocityMultiplier) +
  surgeBonus
);


// ====================================================================
// SECTION 7: ACCUMULATE HEAT
// ====================================================================

const newHeatScore =
  previousScore + earnedPoints;


// ====================================================================
// SECTION 8: CLASSIFY HEAT
// ====================================================================

let heatTag;

if (
  newHeatScore >=
  Number(config.heat_thresholds.hottest_min)
) {

  heatTag = 'HOTTEST';

} else if (
  newHeatScore >=
  Number(config.heat_thresholds.hot_min)
) {

  heatTag = 'HOT';

} else if (
  newHeatScore >=
  Number(config.heat_thresholds.warm_min)
) {

  heatTag = 'WARM';

} else {

  heatTag = 'COLD';

}


// ====================================================================
// SECTION 9: RETURN ENGINE RESULT
// ====================================================================

return {
  email,

  intent_signal: incomingSignal,

  current_rank: currentRank,
  previous_rank: previousRank,
  delta_rank: deltaRank,
  is_intent_upgrade: isIntentUpgrade,

  base_points: basePoints,

  delta_t_seconds: deltaTSeconds,
  velocity_multiplier: velocityMultiplier,

  surge_bonus: surgeBonus,

  earned_points: earnedPoints,

  previous_heat_score: previousScore,
  new_heat_score: newHeatScore,

  heat_tag: heatTag,

  previous_touchpoints: previousTouchpoints,
  updated_touchpoints: previousTouchpoints + 1
};

// 1. Grab data from Domain Cleaner and the incoming item
const domainCleanerData = $('Domain Cleaner').item.json;
const item = $input.item.json;

// 2. High-entropy Unique ID Generator
const timePart = Date.now().toString(36).toUpperCase();
const indexPart = ($itemIndex ?? 0).toString(36).toUpperCase();
const randomPart = Math.random().toString(36).substring(2, 6).toUpperCase();

const generatedLeadId = `LID_${timePart}_${indexPart}_${randomPart}`;

// 3. Merge everything into a SINGLE flat object
return {
  lead_id: generatedLeadId,
  ...domainCleanerData, // Passes all 7 fields from Domain Cleaner
  ...item               // Preserves any Idempotency metadata
   // Appends the new Lead ID
};

// ====================================================================
// UNIFIED ENGINE: META TAG EXTRACTION & CONTEXT NORMALIZATION
// ====================================================================
const item = $input.item?.json || $json || {};

// Safely detect error payload from n8n HTTP node
const isHttpError = Boolean(item && (item.error || item.code === 'ENOTFOUND' || (item.statusCode && item.statusCode >= 400)));
const rawHtml = isHttpError ? '' : String(item.data || item.body || item.html || '');

// 1. SAFELY RECOVER UPSTREAM IDENTITY & PRIMARY KEYS USING STRING LITERALS
const getUpstreamField = (fieldName, fallbackVal = '') => {
  // Check current payload first
  if (item[fieldName] !== undefined && item[fieldName] !== null && item[fieldName] !== '') {
    return item[fieldName];
  }

  // Explicit string literals so n8n can optimize runtime execution
  try {
    const lr = $('Lead Registry').first()?.json;
    if (lr && lr[fieldName] !== undefined && lr[fieldName] !== null && lr[fieldName] !== '') return lr[fieldName];
  } catch (e) {}

  try {
    const dc = $('Domain Cleaner').first()?.json;
    if (dc && dc[fieldName] !== undefined && dc[fieldName] !== null && dc[fieldName] !== '') return dc[fieldName];
  } catch (e) {}

  try {
    const wig = $('Webhook Ingestion Gate').first()?.json;
    if (wig && wig[fieldName] !== undefined && wig[fieldName] !== null && wig[fieldName] !== '') return wig[fieldName];
  } catch (e) {}

  return fallbackVal;
};

const leadId = getUpstreamField('lead_id', 'LID_UNKNOWN');
const email = getUpstreamField('email', 'unknown@domain.com');
const firstName = getUpstreamField('first_name', 'Lead');
const intentSignal = getUpstreamField('intent_signal', 'demo_request');
const extractedDomain = getUpstreamField('extracted_domain', getUpstreamField('domain', ''));

// 2. REGEX PARSING FOR META CONTENT
const getMetaContent = (html, property) => {
  if (!html) return null;
  const regex = new RegExp(`<meta[^>]*(?:name|property)=["']${property}["'][^>]*content=["']([^"']*)["']`, 'i');
  const match = html.match(regex);
  return match ? match[1].trim() : null;
};

let pageTitle = null;
if (rawHtml) {
  const titleMatch = rawHtml.match(/<title[^>]*>([^<]*)<\/title>/i);
  if (titleMatch) pageTitle = titleMatch[1].trim();
}

const metaDescription = getMetaContent(rawHtml, 'description') || getMetaContent(rawHtml, 'og:description');
const metaKeywords = getMetaContent(rawHtml, 'keywords');
const siteName = getMetaContent(rawHtml, 'og:site_name');

// 3. CONSTRUCT CONTEXT SUMMARY & RESOLVE FIELDS
const fallbackContext = [
  pageTitle ? `Title: ${pageTitle}` : '',
  metaDescription ? `Description: ${metaDescription}` : '',
  metaKeywords ? `Keywords: ${metaKeywords}` : ''
].filter(Boolean).join(' | ');

const resolvedName = siteName || (extractedDomain ? extractedDomain.split('.')[0].toUpperCase() : 'UNKNOWN_SCRAPED');

// Extract clean error string safely
let errDetails = 'Host offline or blocked';
if (isHttpError && item.error) {
  errDetails = typeof item.error === 'string' ? item.error : (item.error.message || errDetails);
}
const resolvedDesc = isHttpError 
  ? `Scrape Unreachable: ${errDetails}` 
  : (metaDescription || pageTitle || 'No site metadata available');

// ====================================================================
// RETURN STANDARDIZED PAYLOAD FOR SCORING & DB MAPPER
// ====================================================================
return {
  // Guaranteed Core Database Identifiers
  lead_id: leadId,
  email: email,
  first_name: firstName,
  intent_signal: intentSignal,
  extracted_domain: extractedDomain,

  // Scraped Metadata / Error Fallbacks
  company_name: resolvedName,
  company_description: resolvedDesc,
  company_keywords: metaKeywords || 'NONE',
  raw_meta_summary: fallbackContext || (isHttpError ? 'Site offline or scraping failed' : 'Direct site lookup yielded no meta tags'),
  enrichment_success: false,

  // Deterministic Scoring Normalization
  annual_revenue: 0,
  employee_count: 0,
  funding_stage: "bootstrapped",
  status: "WEB_ENRICHED",
  enrichment_source: isHttpError ? "META_SCRAPER_FAILED" : "META_SCRAPER"
};

