const current = $json ?? {};

const payload = $('Domain Cleaner').item.json ?? {};
const I_D = $('Idempotency & Cooldown').item.json ?? {};
const scored = $('Leads Frequency Scoring').item.json ?? {};

return {
  ...payload,
  ...I_D,
  ...scored,
  ...current
};

// ====================================================================
// SYSTEM ERROR HANDLER NODE — ERROR SANITIZER
// Handles both lead-processing failures and system-only failures.
// ====================================================================

const errorData = $input.first()?.json || {};

const execution = errorData.execution || {};
const lastError = execution.error || errorData.error || {};
const originalData =
  errorData.data ||
  errorData.item?.json ||
  {};

const nodeInfo =
  typeof lastError.node === 'object' &&
  lastError.node !== null
    ? lastError.node
    : typeof errorData.node === 'object' &&
      errorData.node !== null
      ? errorData.node
      : {};

const captureTimestamp = new Date().toISOString();

const fallbackId = `LID_CRASH_${execution.id || Date.now()}`;

const resolvedLeadId = String(
  originalData.lead_id ||
  originalData.body?.lead_id ||
  fallbackId
);

const workflowName = String(
  errorData.workflow?.name ||
  'Lead Engine Workflow'
);

const failedNodeName = String(
  nodeInfo.name ||
  (typeof lastError.node === 'string'
    ? lastError.node
    : '') ||
  (typeof errorData.node === 'string'
    ? errorData.node
    : '') ||
  'Unknown Node'
);

const rawErrorMessage = String(
  lastError.message ||
  errorData.message ||
  'SYSTEM_CRASH_UNHANDLED'
);

return [
  {
    json: {
      // Lead context — available when the failure occurred
      lead_id: resolvedLeadId,

      first_name: String(
        originalData.first_name ||
        originalData.body?.first_name ||
        'Unknown'
      ),

      email: String(
        originalData.email ||
        originalData.body?.email ||
        'UNKNOWN_EMAIL'
      ),

      intent_signal: String(
        originalData.intent_signal ||
        originalData.body?.intent_signal ||
        'UNKNOWN'
      ),

      // System error context
      workflow_name: workflowName,
      failed_node: failedNodeName,
      error_message: rawErrorMessage,
      execution_id: String(execution.id || 'N/A'),
      captured_at: captureTimestamp,

      // Complete database record
      failure_reason:
        `${workflowName} - Node: [${failedNodeName}] - ${rawErrorMessage}`,

      status: 'SYSTEM_EXECUTION_FAILURE'
    }
  }
];

